#!/usr/bin/env python3
"""Compute deterministic ground truth for CSX-188_Q2."""

from __future__ import annotations

import datetime as dt
import html
import json
import re
from pathlib import Path
from typing import Any


TASK_ID = "CSX-188_Q2"
EVENT_ID = "CSX-188"
DIFFICULTY_LEVEL = "L2"

TASK_DIR = Path(__file__).resolve().parent
PACKAGE_ROOT = TASK_DIR.parents[2] / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID
OUTPUT_PATH = TASK_DIR / "computed_gt.json"
REVIEW_PATH = TASK_DIR / "review.json"

ANCHOR_PATH = "data/event_reports/event_reports_003_Locked_event_anchor_2023_Greece_wildfires.json"
REPORT_PATH = "data/event_reports/event_reports_004_Locked_anchor_report_NASA_Earth_Observatory.html"
DNBR_PATH = "data/physical_hazard/physical_hazard_009_Sentinel-2_SR_Harmonized_dNBR.json"
META_PATH = "metadata/event.json"

MONTHS = {
    "january": 1,
    "february": 2,
    "march": 3,
    "april": 4,
    "may": 5,
    "june": 6,
    "july": 7,
    "august": 8,
    "september": 9,
    "october": 10,
    "november": 11,
    "december": 12,
}


RUBRIC = {
    "total_points": 20,
    "criteria": [
        {
            "name": "Returned JSON shape",
            "points": 3,
            "description": "Includes exactly the requested eight fields with compact scalar values and the required final_label.",
            "partial_credit": "Minor key-order or numeric presentation differences are acceptable; missing required fields or using non-JSON prose loses most credit.",
        },
        {
            "name": "Window reconstruction",
            "points": 4,
            "description": "Uses the locked 2023-07-01/2023-08-31 window, computes 62 inclusive days, and extracts the 2023-08-22/2023-08-23 narrative date span.",
            "partial_credit": "Award up to 2 points for one correct window and up to 1 point for using exclusive rather than inclusive day counting.",
        },
        {
            "name": "Cue counts",
            "points": 5,
            "description": "Reports active_fire_cues=4, smoke_transport_cues=5, and settlement_impact_cues=4 from the report narrative.",
            "partial_credit": "Award about 1.5 points per correct cue family, with small credit for identifying the right family but missing one cue.",
        },
        {
            "name": "dNBR extraction",
            "points": 3,
            "description": "Reports dnbr_max=0.86 after rounding the satellite dNBR peak value 0.8597047915007765 to three decimals.",
            "partial_credit": "Award 2 points for the right unrounded value with different presentation, or 1 point for using the dNBR mean instead of the peak.",
        },
        {
            "name": "Threshold arithmetic",
            "points": 3,
            "description": "Applies active_fire_cues >= 3, smoke_transport_cues >= 4, settlement_impact_cues >= 2, and dnbr_max >= 0.660.",
            "partial_credit": "Award roughly 0.75 points per correctly evaluated threshold.",
        },
        {
            "name": "Computed interpretation",
            "points": 2,
            "description": "Keeps the interpretation concise and limited to the computed smoke-plus-burn ledger.",
            "partial_credit": "Award 1 point if the label is right but the explanation converts qualitative report words into exact loss or area totals.",
        },
    ],
}


def load_json(relative_path: str) -> dict[str, Any]:
    with (PACKAGE_ROOT / relative_path).open("r", encoding="utf-8-sig") as handle:
        return json.load(handle)


def load_text(relative_path: str) -> str:
    return (PACKAGE_ROOT / relative_path).read_text(encoding="utf-8", errors="replace")


def strip_html(source: str) -> str:
    source = re.sub(r"(?is)<script.*?</script>", " ", source)
    source = re.sub(r"(?is)<style.*?</style>", " ", source)
    source = re.sub(r"(?is)<[^>]+>", " ", source)
    source = html.unescape(source)
    return re.sub(r"\s+", " ", source).strip()


def report_narrative(report_html: str) -> str:
    paragraphs = re.findall(r"(?is)<p\b[^>]*>(.*?)</p>", report_html)
    text = " ".join(strip_html(paragraph) for paragraph in paragraphs)
    marker = "A month after"
    if marker in text:
        text = text[text.index(marker) :]
    if "References & Resources" in text:
        text = text.split("References & Resources", 1)[0]
    return re.sub(r"\s+", " ", text).strip()


def norm(text: str) -> str:
    return re.sub(r"\s+", " ", text.lower()).strip()


def contains_all(text: str, phrases: list[str]) -> bool:
    lowered = norm(text)
    return all(phrase.lower() in lowered for phrase in phrases)


def inclusive_days(start_date: str, end_date: str) -> int:
    start = dt.date.fromisoformat(start_date)
    end = dt.date.fromisoformat(end_date)
    return (end - start).days + 1


def narrative_date_span(text: str, default_year: int) -> str:
    dates: list[dt.date] = []
    pattern = re.compile(
        r"\b("
        + "|".join(MONTHS)
        + r")\s+(\d{1,2})(?!\d)(?:,\s*(\d{4}))?",
        flags=re.IGNORECASE,
    )
    for match in pattern.finditer(text):
        month = MONTHS[match.group(1).lower()]
        day = int(match.group(2))
        year = int(match.group(3) or default_year)
        dates.append(dt.date(year, month, day))
    if not dates:
        raise ValueError("No narrative dates found in report text")
    return f"{min(dates).isoformat()}/{max(dates).isoformat()}"


def cue_flags(text: str) -> dict[str, dict[str, bool]]:
    return {
        "active_fire": {
            "many_new_fires_within_24h": contains_all(text, ["dozens more fires", "within 24 hours"]),
            "other_fires_elsewhere": contains_all(text, ["other fires", "elsewhere"]),
            "extreme_fire_weather": contains_all(text, ["extreme fire weather"]),
            "hot_dry_windy_continuing": contains_all(text, ["hot, dry, and windy", "continue on august 23"]),
        },
        "smoke_transport": {
            "alexandroupolis_origin": contains_all(text, ["near alexandroupolis"]),
            "long_plume_to_italy": contains_all(text, ["plume of smoke", "hundreds of miles", "toward italy"]),
            "satellite_observed_plume": contains_all(text, ["visible in this image", "august 22", "viirs"]),
            "capital_city_smoke": contains_all(text, ["smoke wafting over the capital city"]),
            "mediterranean_smoke": contains_all(text, ["smoke was detected over italy", "northern africa"]),
        },
        "settlement_impact": {
            "athens_fire": contains_all(text, ["fires near athens"]),
            "homes_burned": contains_all(text, ["burned homes"]),
            "cars_burned": contains_all(text, ["cars"]),
            "capital_city_smoke": contains_all(text, ["capital city", "smoke"]),
        },
    }


def count_true(values: dict[str, bool]) -> int:
    return sum(1 for value in values.values() if value)


def build_review(primary_gt: dict[str, Any]) -> dict[str, Any]:
    compact_bytes = len(json.dumps(primary_gt, ensure_ascii=True, separators=(",", ":")))
    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "status": "approved",
        "reviewer": "codex",
        "checks": {
            "english_only": True,
            "no_question_leakage": True,
            "computed_gt_reproducible": True,
            "solution_has_rubric": True,
            "primary_gt_compact": compact_bytes < 1200 and len(primary_gt) <= 8,
            "uses_real_package_data": True,
            "no_legacy_fields": True,
        },
        "notes": [
            "Task uses report-window reconstruction, cue counting, and dNBR extraction from local records.",
            "The answer has an exact numeric core with rubric-scored reasoning.",
        ],
    }


def main() -> None:
    meta = load_json(META_PATH)
    anchor = load_json(ANCHOR_PATH)
    dnbr = load_json(DNBR_PATH)
    report_html = load_text(REPORT_PATH)
    narrative = report_narrative(report_html)

    start_date = anchor["temporal_window"]["start_date"]
    end_date = anchor["temporal_window"]["end_date"]
    flags = cue_flags(narrative)
    dnbr_stats = dnbr["stats"]
    dnbr_max_raw = float(dnbr_stats["sentinel2_dnbr_max"])
    dnbr_max = round(dnbr_max_raw, 3)

    active_fire_cues = count_true(flags["active_fire"])
    smoke_transport_cues = count_true(flags["smoke_transport"])
    settlement_impact_cues = count_true(flags["settlement_impact"])
    gates = {
        "active_fire_cues_ge_3": active_fire_cues >= 3,
        "smoke_transport_cues_ge_4": smoke_transport_cues >= 4,
        "settlement_impact_cues_ge_2": settlement_impact_cues >= 2,
        "dnbr_max_ge_0_660": dnbr_max_raw >= 0.660,
    }
    final_label = (
        "passes_smoke_burn_window_ledger"
        if all(gates.values())
        else "does_not_pass_smoke_burn_window_ledger"
    )

    primary_gt = {
        "event_window": f"{start_date}/{end_date}",
        "event_window_days": inclusive_days(start_date, end_date),
        "narrative_date_span": narrative_date_span(narrative, default_year=2023),
        "active_fire_cues": active_fire_cues,
        "smoke_transport_cues": smoke_transport_cues,
        "settlement_impact_cues": settlement_impact_cues,
        "dnbr_max": dnbr_max,
        "final_label": final_label,
    }

    computed_gt = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "numeric",
        "target_family": "wildfire_smoke_burn_threshold_ledger",
        "evaluation_mode": "hybrid",
        "difficulty_level": DIFFICULTY_LEVEL,
        "primary_gt": primary_gt,
        "key_values": {
            "event_name": meta["event_name"],
            "hazard_family": meta["hazard_family"],
            "cue_flags": flags,
            "cue_counts": {
                "active_fire_cues": active_fire_cues,
                "smoke_transport_cues": smoke_transport_cues,
                "settlement_impact_cues": settlement_impact_cues,
            },
            "dnbr_stats": {
                "sentinel2_dnbr_max_raw": dnbr_max_raw,
                "sentinel2_dnbr_mean": dnbr_stats["sentinel2_dnbr_mean"],
                "sentinel2_dnbr_min": dnbr_stats["sentinel2_dnbr_min"],
                "sentinel2_dnbr_stdDev": dnbr_stats["sentinel2_dnbr_stdDev"],
            },
            "gates": gates,
            "required_metrics": [
                "event_window_days",
                "narrative_date_span",
                "active_fire_cues",
                "smoke_transport_cues",
                "settlement_impact_cues",
                "dnbr_max",
                "final_label",
            ],
            "formulae": {
                "event_window_days": "inclusive day count from locked start and end dates",
                "cue_count": "count of true report-text tests in each named cue family",
                "dnbr_max": "round(sentinel2_dnbr_max, 3)",
                "final_label": "all four threshold tests must pass",
            },
        },
        "tolerances": {
            "date": "exact",
            "integer_count_abs": 0,
            "dnbr_abs": 0.001,
            "final_label": "exact",
        },
        "rubric": RUBRIC,
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [META_PATH, ANCHOR_PATH, REPORT_PATH, DNBR_PATH],
        },
    }

    OUTPUT_PATH.write_text(json.dumps(computed_gt, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    REVIEW_PATH.write_text(json.dumps(build_review(primary_gt), indent=2, sort_keys=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
